/* Finbar's Photo Map — a small map of photographed places.
 *
 * Data comes from photos.json, generated by tools/prep.py.
 * Each entry: { id, file, thumb, lat, lon, date, width, height }
 */
(function () {
  'use strict';

  // Esri's World Topographic Map: coloured terrain with blue water and
  // labels, no API key. Served through zoom 19, so no upscaling needed.
  var TILES =
    'https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}';
  var ATTRIBUTION = '&copy; Esri, OSM';

  // The map opens fully zoomed out, centred on this longitude (Sydney).
  var START_LNG = 151.2093;

  // Smooth wheel/pinch zoom gains, as a multiplier on Leaflet's natural
  // per-gesture amount (1 = what Leaflet would move, without snapping). Ease
  // is the fraction of the remaining distance covered each animation frame.
  var WHEEL_GAIN = 1.5;
  var PINCH_GAIN = 5;
  var ZOOM_EASE = 0.2;

  // Touch gestures in the viewer. A drag only counts once it clearly follows
  // one axis: SWIPE_MIN horizontally to change photo, CLOSE_MIN downward to
  // dismiss, AXIS_RATIO the dominance the axis needs.
  var SWIPE_MIN = 40;
  var CLOSE_MIN = 90;
  var AXIS_RATIO = 1.2;

  // Double-tap then drag (one finger) to zoom the map continuously, the way
  // map apps do. A second tap within DOUBLE_TAP_MS and DOUBLE_TAP_DIST arms
  // it; a vertical drag past ZOOM_DRAG_START then drives the zoom by
  // ZOOM_DRAG_PX pixels per level, anchored on the tap.
  var DOUBLE_TAP_MS = 300;
  var DOUBLE_TAP_DIST = 30;
  var ZOOM_DRAG_START = 6;
  var ZOOM_DRAG_PX = 110;
  // Drag eases faster than the wheel so the map tracks the finger closely.
  var ZOOM_DRAG_EASE = 0.3;

  // The primary pointer is coarse (phone/tablet), not a window width: it
  // decides swipe navigation, the one-off hint, and hiding the album arrows.
  // A touch-laptop whose main pointer is a mouse keeps its arrows.
  var isTouch =
    window.matchMedia && window.matchMedia('(pointer: coarse)').matches;

  // sessionStorage, never a cookie: the swipe hint is per browser session.
  var HINT_KEY = 'photomap:swipe-hint';

  var state = {
    photos: [],
    map: null,
    markerGroup: null,
    lastFocus: null,
    loadToken: 0,
    // Photos currently navigable in the viewer. A lone marker is a one-item
    // album (no arrows); a cluster opens its own photos.
    album: [],
    albumIndex: 0,
    // Live touch gesture in the viewer: start point, running delta, and a
    // flag that swallows the click a swipe/drag synthesises on release.
    gesture: { active: false, x: 0, y: 0, dx: 0, dy: 0, suppressClick: false },
    // One-off swipe hint bookkeeping.
    hintTimer: null,
    hintShown: false
  };

  var el = {};

  function $(id) {
    return document.getElementById(id);
  }

  function cacheElements() {
    el.map = $('map');
    el.status = $('status');
    el.viewer = $('viewer');
    el.image = $('viewer-img');
    el.spinner = $('viewer-spinner');
    el.close = $('viewer-close');
    el.prev = $('viewer-prev');
    el.next = $('viewer-next');
    el.date = $('viewer-date');
    el.count = $('viewer-count');
    el.hint = $('viewer-hint');
  }

  /* ----------------------------------------------------------- helpers --- */

  function status(message) {
    if (!message) {
      el.status.hidden = true;
      el.status.textContent = '';
      return;
    }
    el.status.textContent = message;
    el.status.hidden = false;
  }

  function formatDate(value) {
    if (!value) return '';
    var parts = /^(\d{4})-(\d{2})-(\d{2})/.exec(value);
    if (!parts) return value;
    var date = new Date(Number(parts[1]), Number(parts[2]) - 1, Number(parts[3]));
    return date.toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  }

  function describe(photo) {
    var date = formatDate(photo.date);
    return date ? 'Photo from ' + date : 'Photo';
  }

  function readHash() {
    try {
      return decodeURIComponent(window.location.hash.replace(/^#/, ''));
    } catch (error) {
      return '';
    }
  }

  /* --------------------------------------------------------------- map --- */

  // Markers are small square thumbnails; a cluster is a stack of them.
  var THUMB_PX = 44;
  var STACK_PX = 58;

  // A photo sits at one longitude, but the map tiles repeat horizontally, so
  // the same marker is placed in a few world copies (360 deg each) to keep
  // every visible copy of the map populated. Fixed and finite: at the lowest
  // zoom (2) the world is 1024px wide, and two copies per side covers any
  // realistic viewport (up to ~4K).
  var WORLD_COPIES = 2;

  function thumbUrl(photo) {
    return photo.thumb || photo.file;
  }

  function thumbIcon(photo) {
    return L.divIcon({
      className: 'photo-thumb',
      html: '<img src="' + thumbUrl(photo) + '" alt="" loading="lazy" decoding="async">',
      iconSize: [THUMB_PX, THUMB_PX],
      iconAnchor: [THUMB_PX / 2, THUMB_PX / 2]
    });
  }

  // Up to three photos from the cluster, spread across it, for the stack.
  function stackPhotos(markers, limit) {
    if (markers.length <= limit) return markers.slice();
    var picked = [];
    for (var i = 0; i < limit; i += 1) {
      picked.push(markers[Math.round((i * (markers.length - 1)) / (limit - 1))]);
    }
    return picked;
  }

  function clusterIcon(cluster) {
    var markers = cluster.getAllChildMarkers();
    var count = cluster.getChildCount();
    var photos = stackPhotos(markers, 3).filter(function (marker) {
      return marker.photo;
    });

    var cards = photos
      .map(function (marker) {
        return (
          '<img src="' + thumbUrl(marker.photo) + '" alt="" loading="lazy" decoding="async">'
        );
      })
      .join('');

    return L.divIcon({
      className: 'cluster-stack',
      html:
        '<div class="stack stack-' + photos.length + '" aria-label="' +
        count.toLocaleString() + ' photos">' + cards + '</div>',
      iconSize: [STACK_PX, STACK_PX],
      iconAnchor: [STACK_PX / 2, STACK_PX / 2]
    });
  }

  // Keep the whole world no taller than the window: at the furthest-out zoom
  // the map fills the height exactly, so there is no vertical panning and no
  // empty background above or below. Recomputed when the window is resized.
  function fitMinZoomToWindow() {
    var zoom = state.map.getZoom();
    var worldHeight = state.map.getPixelWorldBounds(zoom).getSize().y;
    var target = zoom + Math.log(state.map.getSize().y / worldHeight) / Math.LN2;
    state.map.setMinZoom(Math.max(0, Math.min(target, state.map.getMaxZoom())));
  }

  // Smooth wheel/pinch zoom. Leaflet's built-in handler applies zoom in
  // debounced jumps; this eases the map toward a target zoom every animation
  // frame so scrolling and pinching glide, keeping the point under the pointer
  // fixed. Replaces Leaflet's handler (scrollWheelZoom is off).
  function enableSmoothZoom(map) {
    var target = map.getZoom();
    var anchor = null;
    var frame = null;
    // Fraction of the remaining zoom covered each frame. The drag gesture
    // raises this for a tighter feel; every other path resets it.
    var ease = ZOOM_EASE;
    // Integer zoom level markercluster is currently showing.
    var shownLevel = Math.round(map.getZoom());

    // The amount Leaflet would move for a wheel delta, without the snapping.
    // The saturating curve stops a fast flick from running away.
    function levelsFor(delta) {
      var x = delta / (4 * 60);
      var magnitude = 4 * Math.log(2 / (1 + Math.exp(-Math.abs(x)))) / Math.LN2;
      return delta < 0 ? -magnitude : magnitude;
    }

    function clampZoom(zoom) {
      return Math.max(map.getMinZoom(), Math.min(map.getMaxZoom(), zoom));
    }

    // The centre that keeps `point` under the pointer at `zoom`.
    function centerFor(point, zoom) {
      var scale = map.getZoomScale(zoom);
      var half = map.getSize().divideBy(2);
      return map.containerPointToLatLng(
        half.add(point.subtract(half).multiplyBy(1 - 1 / scale))
      );
    }

    function finish() {
      frame = null;
      ease = ZOOM_EASE;
      var zoom = map.getZoom();
      map.setView(anchor ? centerFor(anchor, zoom) : map.getCenter(), zoom, {
        animate: false
      });
      // setView already set this zoom during the gesture, so it fires no
      // zoomend itself; fire one if we have not already shown this level.
      if (Math.round(zoom) !== shownLevel) {
        shownLevel = Math.round(zoom);
        map.fire('zoomend');
      }
    }

    function step() {
      var diff = target - map.getZoom();
      if (Math.abs(diff) < 1e-3) {
        finish();
        return;
      }
      var zoom = map.getZoom() + diff * ease;
      // Apply the same centre clamp setView will use at the end, every frame,
      // so approaching the zoom-out limit eases into it instead of snapping.
      var center = map._limitCenter(
        centerFor(anchor, zoom),
        zoom,
        map.options.maxBounds
      );
      // Move without the normal move/zoomend bookkeeping; we drive those
      // ourselves. When the rounded zoom level changes, tell markercluster so
      // it splits/merges now instead of after the whole gesture.
      map._move(center, zoom, { pinch: true }, true);
      var level = Math.round(zoom);
      if (level !== shownLevel) {
        shownLevel = level;
        map.fire('zoomend');
      }
      frame = requestAnimationFrame(step);
    }

    function startFrame() {
      if (!frame) frame = requestAnimationFrame(step);
    }

    function onWheel(event) {
      L.DomEvent.preventDefault(event);
      map._stop();
      var gain = event.ctrlKey ? PINCH_GAIN : WHEEL_GAIN;
      ease = ZOOM_EASE;
      target = clampZoom(target + levelsFor(L.DomEvent.getWheelDelta(event)) * gain);
      anchor = map.mouseEventToContainerPoint(event);
      startFrame();
    }

    map.getContainer().addEventListener('wheel', onWheel, { passive: false });

    // Keep the target in step with zooms we did not drive (the zoom buttons,
    // keyboard), so the next gesture does not jump.
    function syncTarget() {
      if (!frame) target = map.getZoom();
      shownLevel = Math.round(map.getZoom());
    }
    map.on('zoomend', syncTarget);
    map.on('dragstart', function () {
      if (frame) cancelAnimationFrame(frame);
      frame = null;
      target = map.getZoom();
      // worldCopyJump caches the world width on zoomend, but this smooth zoom
      // changes zoom via _move and only fires zoomend at rounded levels. The
      // cache can therefore be stale when a drag wraps, shifting the map by a
      // fraction of a world. Refresh it at the real current zoom.
      if (map.dragging) map.dragging._onZoomEnd();
    });

    // Driven by the double-tap-drag gesture, which shares this easing loop.
    return {
      zoomTo: function (zoom, point, dragEase) {
        anchor = point;
        ease = dragEase || ZOOM_EASE;
        target = clampZoom(zoom);
        startFrame();
      }
    };
  }

  // Double-tap then drag (one finger) to zoom continuously, like a map app.
  // Leaflet's discrete double-click zoom never fires from touch, so this owns
  // the gesture on touch devices: a second tap within a short window arms it,
  // a vertical drag drives the smooth zoom anchored on the tap, and a plain
  // double-tap zooms in one level. Capture-phase listeners run before
  // Leaflet's panning so the second tap never becomes a drag.
  function enableDoubleTapDragZoom(map, smoothZoom) {
    if (!isTouch) return;

    var container = map.getContainer();
    var lastTap = null;
    var armed = null;
    var zooming = false;

    function cancel() {
      armed = null;
      zooming = false;
    }

    function onStart(event) {
      if (!container.contains(event.target)) return;
      // Let the Leaflet zoom buttons own their taps; do not arm on them.
      if (event.target.closest && event.target.closest('.leaflet-control')) {
        lastTap = null;
        cancel();
        return;
      }
      if (event.touches.length !== 1) {
        // A second finger means pinch, not double-tap.
        lastTap = null;
        cancel();
        return;
      }
      var touch = event.touches[0];
      var now = Date.now();
      if (
        lastTap &&
        now - lastTap.time <= DOUBLE_TAP_MS &&
        Math.abs(touch.clientX - lastTap.x) <= DOUBLE_TAP_DIST &&
        Math.abs(touch.clientY - lastTap.y) <= DOUBLE_TAP_DIST
      ) {
        lastTap = null;
        armed = {
          anchor: map.mouseEventToContainerPoint(touch),
          startY: touch.clientY,
          startZoom: map.getZoom()
        };
        zooming = false;
        // Claim the second tap: stop it reaching Leaflet (so it is not read as
        // a pan) and cancel its default click/focus, so a clamped gesture
        // cannot activate whatever sits under the finger (a zoom button, say).
        event.stopPropagation();
        if (event.cancelable) event.preventDefault();
        return;
      }

      lastTap = { time: now, x: touch.clientX, y: touch.clientY };
    }

    function onMove(event) {
      if (!armed || event.touches.length !== 1) return;
      if (event.cancelable) event.preventDefault();
      var touch = event.touches[0];
      // Google Maps direction: dragging down zooms in, up zooms out.
      var dy = touch.clientY - armed.startY;
      if (!zooming) {
        if (Math.abs(dy) < ZOOM_DRAG_START) return;
        zooming = true;
        armed.dragStartY = touch.clientY;
        armed.dragStartZoom = map.getZoom();
      }
      smoothZoom.zoomTo(
        armed.dragStartZoom + (touch.clientY - armed.dragStartY) / ZOOM_DRAG_PX,
        armed.anchor,
        ZOOM_DRAG_EASE
      );
    }

    function onEnd(event) {
      if (!armed) return;
      var wasZooming = zooming;
      var anchor = armed.anchor;
      cancel();
      if (event.cancelable) event.preventDefault();
      if (wasZooming) return;
      // A plain double-tap zooms in one level, like the desktop double-click.
      smoothZoom.zoomTo(map.getZoom() + 1, anchor);
    }

    function onCancel() {
      lastTap = null;
      cancel();
    }

    document.addEventListener('touchstart', onStart, { passive: false, capture: true });
    document.addEventListener('touchmove', onMove, { passive: false, capture: true });
    document.addEventListener('touchend', onEnd, { passive: false, capture: true });
    document.addEventListener('touchcancel', onCancel, { passive: false, capture: true });
  }

  // Leaflet ends the one-finger drag the moment a second finger lands
  // (Draggable._onDown calls finishDrag for a multi-touch touchstart), and
  // TouchZoom._onTouchEnd responds by starting a ~250ms zoom animation to the
  // pinched view instead of restarting a drag for the finger still down.
  // Draggable ignores every touch while that animation runs, so the remaining
  // finger cannot pan and a fresh touch right after is dead as well. The map
  // is already at that view (the pinch moved it frame by frame), so finish the
  // animation as soon as the user is still touching, then re-arm the drag.
  // This reaches into Leaflet internals, so it is pinned to the vendored 1.9.4
  // and must be re-checked if Leaflet is updated.
  function enableTouchPanHandoff(map) {
    if (!isTouch) return;

    var touches = 0;
    var pinching = false;
    var lastTouch = null;

    // End the pinch-release animation now instead of waiting it out.
    function settle() {
      if (map._animatingZoom) map._onZoomTransitionEnd();
    }

    function track(event) {
      touches = event.touches.length;
      if (touches > 1) pinching = true;
      lastTouch = event.touches[0] || lastTouch;
    }

    var container = map.getContainer();
    // A fresh touch during the release animation must be able to pan at once.
    // Run on the document in the capture phase so the animation is gone before
    // Leaflet's own (container) touchstart handler decides to ignore the drag.
    document.addEventListener(
      'touchstart',
      function (event) {
        if (container.contains(event.target)) settle();
      },
      { passive: true, capture: true }
    );
    container.addEventListener('touchstart', track, { passive: true });
    container.addEventListener('touchmove', track, { passive: true });
    container.addEventListener(
      'touchend',
      function (event) {
        track(event);
        if (event.touches.length === 0) pinching = false;
        if (event.touches.length !== 1 || !pinching) return;
        // Let Leaflet's own touchend handler start the release animation
        // before resume() ends it and re-arms the drag.
        setTimeout(resume, 0);
      },
      { passive: true }
    );
    container.addEventListener(
      'touchcancel',
      function (event) {
        track(event);
        if (event.touches.length === 0) pinching = false;
      },
      { passive: true }
    );

    function resume() {
      if (touches !== 1 || !pinching || !lastTouch) return;
      settle();
      var draggable = map.dragging && map.dragging._draggable;
      if (!draggable || draggable._moving) return;
      var touch = lastTouch;
      lastTouch = null;
      pinching = false;
      draggable._onDown({
        touches: [touch],
        type: 'touchstart',
        target: touch.target,
        clientX: touch.clientX,
        clientY: touch.clientY,
        which: 1,
        button: 1
      });
    }
  }

  function initMap() {
    var map = L.map(el.map, {
      zoomControl: false,
      minZoom: 2,
      // Cap at city level: zoom 12 shows a whole city and its main streets
      // without dropping to street-level detail, which starts around 13.
      maxZoom: 12,
      // No snapping: the window-fitted fractional min zoom set by
      // fitMinZoomToWindow() must be reachable, and snapping would round it
      // back up to 2.
      zoomSnap: 0,
      // Wheel/pinch zoom is handled by enableSmoothZoom() below.
      scrollWheelZoom: false,
      // Double-tap zoom is ours on touch (enableDoubleTapDragZoom); keep
      // Leaflet's double-click handler for mouse/desktop.
      doubleClickZoom: !isTouch,
      // Long-press context menu is unused and would fight double-tap-drag.
      tapHold: false,
      // Panning past the antimeridian re-centres by a full world instead of
      // sliding into an empty copy of the map with no dots on it.
      worldCopyJump: true,
      // Stop the view leaving the map's top and bottom edges. Latitude is
      // clipped to Web Mercator's extent; longitude spans several worlds so
      // horizontal wrap still works and the extra marker copies stay reachable.
      maxBounds: [[-85.051129, -1440], [85.051129, 1440]],
      maxBoundsViscosity: 1,
      attributionControl: true
    }).setView([0, START_LNG], 2);

    // Drop Leaflet's flag/link prefix; the source credit is all we show.
    map.attributionControl.setPrefix(false);

    L.tileLayer(TILES, {
      attribution: ATTRIBUTION,
      maxZoom: 12,
      maxNativeZoom: 19,
      // Leaflet defaults this to L.Browser.mobile, which is true on iOS Safari
      // (it still defines window.orientation), so tiles would only load on
      // moveend and the map blanks out mid-pan. Load during the pan instead,
      // like desktop.
      updateWhenIdle: false
    }).addTo(map);

    L.control.zoom({ position: 'bottomright' }).addTo(map);

    state.map = map;

    var smoothZoom = enableSmoothZoom(map);
    enableDoubleTapDragZoom(map, smoothZoom);
    enableTouchPanHandoff(map);

    // Set the zoom floor before the cluster group is created: markercluster
    // builds its zoom grids from the map's min zoom when it is added and does
    // not rebuild them if the floor changes later.
    fitMinZoomToWindow();
    map.on('resize', fitMinZoomToWindow);
    // Open fully zoomed out on Sydney instead of fitted to the photos.
    map.setView([0, START_LNG], map.getMinZoom(), { animate: false });

    // markercluster pads the visible bounds by a full screen before pruning,
    // but only for non-mobile: with L.Browser.mobile it prunes against the raw
    // viewport bounds. iOS Safari defines window.orientation, so Leaflet
    // reports mobile there and pruning lands exactly on the viewport edge:
    // panning tears down and rebuilds on-screen clusters, and a left/right
    // jiggle across that edge unloads and reloads everything beyond it. Use
    // the desktop padding on every platform. Like the animation patch below,
    // this reaches into a markercluster internal and is pinned to the vendored
    // version.
    L.MarkerClusterGroup.prototype._getExpandedVisibleBounds = function () {
      if (!this.options.removeOutsideVisibleBounds) return this._mapBoundsInfinite;
      return this._checkBoundsMaxLat(this._map.getBounds().pad(1));
    };

    state.markerGroup = L.markerClusterGroup({
      showCoverageOnHover: false,
      // Clicking a stack opens its album instead of zooming/spiderfying.
      // Turning both defaults off stops markercluster registering its own
      // click handler; ours is bound just below.
      spiderfyOnMaxZoom: false,
      zoomToBoundsOnClick: false,
      // Prune clusters that leave the view, otherwise stacks from earlier zoom
      // levels linger as ghosts. Add every marker up front (no chunked
      // loading) so pruning never misses the ones that should be visible.
      removeOutsideVisibleBounds: true,
      chunkedLoading: false,
      // Animate stacks joining/splitting as the level changes. This is only
      // safe because we fire zoomend during the smooth zoom and prune
      // off-screen clusters.
      animate: true,
      // Thumbnails are 44px wide, so cluster anything closer than that.
      maxClusterRadius: 60,
      // Spread spiderfied thumbnails out so they do not cover each other.
      spiderfyDistanceMultiplier: 1.6,
      iconCreateFunction: clusterIcon
    }).addTo(map);

    state.markerGroup.on('clusterclick clusterkeypress', onClusterClick);

    // markercluster fades a joining cluster into the incoming stack by moving
    // and hiding its outgoing children. Its own version only reaches direct
    // markers and child clusters exactly one level down, so a nested stack or
    // a lone photo under a single-parent chain stays opaque until the cleanup
    // timer pops it. Walk every descendant instead: photos and clusters share
    // _icon / _setPos / clusterHide, so one recursion fades them all the same.
    //
    // This patches a markercluster internal, so it is tied to the vendored
    // version and must be re-checked if that is updated. A cleaner long-term
    // direction is to do our own clustering/render pass over a uniform node
    // tree, where a photo and an n-cluster are the same object and the
    // animation recurses over one children() accessor. That would remove this
    // patch and the last node-type special cases. See AGENTS.md, "Cluster
    // animation".
    L.MarkerCluster.prototype._recursivelyAnimateChildrenIn = function (bounds, point) {
      function hide(node) {
        if (node._icon) {
          node._setPos(point);
          node.clusterHide();
        }
        (node._childClusters || []).forEach(hide);
        (node._markers || []).forEach(hide);
      }
      (this._childClusters || []).forEach(hide);
      (this._markers || []).forEach(hide);
    };
  }

  // The photos in a clicked cluster, oldest first. Markers carry their index
  // into state.photos (already sorted by date), and world-copy duplicates are
  // collapsed by id.
  function clusterAlbum(cluster) {
    var seen = {};
    var markers = [];
    cluster.getAllChildMarkers().forEach(function (marker) {
      var photo = marker.photo;
      if (!photo || seen[photo.id]) return;
      seen[photo.id] = true;
      markers.push(marker);
    });
    markers.sort(function (a, b) {
      return a.photoIndex - b.photoIndex;
    });
    return markers.map(function (marker) {
      return marker.photo;
    });
  }

  function onClusterClick(event) {
    // markercluster fires this for any keypress; only Enter activates a stack.
    if (event.type === 'clusterkeypress') {
      var key = event.originalEvent;
      if (key && key.key !== 'Enter' && key.keyCode !== 13) return;
    }
    var album = clusterAlbum(event.layer);
    if (album.length) open(album, 0);
  }

  function drawPhotos() {
    if (!state.photos.length) return;

    var wraps = [];
    for (var copy = -WORLD_COPIES; copy <= WORLD_COPIES; copy += 1) {
      wraps.push(copy * 360);
    }

    var markers = [];
    state.photos.forEach(function (photo, index) {
      wraps.forEach(function (wrap) {
        var marker = L.marker([photo.lat, photo.lon + wrap], {
          icon: thumbIcon(photo),
          // Only the canonical copy joins the tab order; the wrapped copies
          // are click-only duplicates.
          keyboard: wrap === 0
        });
        marker.photo = photo;
        marker.photoIndex = index;
        marker.on('add', function () {
          // No tooltip: only a screen-reader name.
          var node = marker.getElement();
          if (node) node.setAttribute('aria-label', describe(photo));
        });
        marker.on('click', function () {
          open([photo], 0);
        });
        markers.push(marker);
      });
    });

    state.markerGroup.addLayers(markers);
  }

  /* ------------------------------------------------------------ viewer --- */

  function open(album, index) {
    if (!album || !album.length) return;
    if (index < 0 || index >= album.length) return;

    var photo = album[index];
    state.album = album;
    state.albumIndex = index;

    var wasOpen = !el.viewer.hidden;
    if (!wasOpen) {
      state.lastFocus = document.activeElement;
      el.viewer.hidden = false;
      document.body.classList.add('viewer-open');
      showHint(album);
    }

    var token = ++state.loadToken;

    el.image.classList.remove('is-loaded');
    el.image.removeAttribute('width');
    el.image.removeAttribute('height');
    if (photo.width && photo.height) {
      el.image.setAttribute('width', photo.width);
      el.image.setAttribute('height', photo.height);
    }
    el.image.alt = describe(photo);
    el.spinner.hidden = false;

    el.image.onload = function () {
      if (token !== state.loadToken) return;
      el.spinner.hidden = true;
      el.image.classList.add('is-loaded');
    };
    el.image.onerror = function () {
      if (token !== state.loadToken) return;
      el.spinner.hidden = true;
      status('That photo could not be loaded.');
    };
    el.image.src = photo.file;

    el.date.textContent = formatDate(photo.date);
    if (album.length > 1) {
      el.count.textContent = index + 1 + ' / ' + album.length;
      el.count.hidden = false;
    } else {
      el.count.textContent = '';
      el.count.hidden = true;
    }

    el.viewer.setAttribute('aria-label', describe(photo));
    updateNav();
    replaceHash(photo.id);

    if (!wasOpen) el.close.focus({ preventScroll: true });
  }

  // Move within the open album only; never wrap past its ends.
  function show(delta) {
    open(state.album, state.albumIndex + delta);
  }

  function updateNav() {
    var last = state.album.length - 1;
    el.prev.hidden = state.albumIndex <= 0;
    el.next.hidden = state.albumIndex >= last;

    // Do not leave focus on a control that just disappeared.
    if (document.activeElement === el.prev && el.prev.hidden) {
      focusNav(el.next);
    } else if (document.activeElement === el.next && el.next.hidden) {
      focusNav(el.prev);
    }
  }

  function focusNav(preferred) {
    if (preferred && !preferred.hidden) {
      preferred.focus({ preventScroll: true });
    } else {
      el.close.focus({ preventScroll: true });
    }
  }

  // A translucent hint over the album explaining swipe and drag-down. Shown
  // once per browser session on the first multi-photo album, then fades and
  // never gets in the way: any interaction hides it immediately.
  function hintSeen() {
    try {
      return window.sessionStorage.getItem(HINT_KEY) === '1';
    } catch (error) {
      return state.hintShown;
    }
  }

  function markHintSeen() {
    state.hintShown = true;
    try {
      window.sessionStorage.setItem(HINT_KEY, '1');
    } catch (error) {
      // Storage unavailable (private mode); the in-memory flag still covers
      // this page load.
    }
  }

  function showHint(album) {
    if (!el.hint || !isTouch || album.length < 2 || hintSeen()) return;
    markHintSeen();
    el.hint.classList.add('is-visible');
    state.hintTimer = setTimeout(hideHint, 3500);
  }

  function hideHint() {
    if (state.hintTimer) {
      clearTimeout(state.hintTimer);
      state.hintTimer = null;
    }
    if (el.hint) el.hint.classList.remove('is-visible');
  }

  // Swipe left/right through the album, or drag down to close. Release-to-
  // navigate (no follow) keeps it consistent with the arrow buttons.
  function bindTouchGestures() {
    if (!isTouch) return;

    el.viewer.addEventListener(
      'touchstart',
      function (event) {
        hideHint();
        var gesture = state.gesture;
        var onButton =
          event.target &&
          event.target.closest &&
          event.target.closest('button');
        if (event.touches.length !== 1 || onButton) {
          gesture.active = false;
          return;
        }
        gesture.active = true;
        gesture.x = event.touches[0].clientX;
        gesture.y = event.touches[0].clientY;
        gesture.dx = 0;
        gesture.dy = 0;
      },
      { passive: true }
    );

    el.viewer.addEventListener(
      'touchmove',
      function (event) {
        var gesture = state.gesture;
        if (!gesture.active || event.touches.length !== 1) return;
        gesture.dx = event.touches[0].clientX - gesture.x;
        gesture.dy = event.touches[0].clientY - gesture.y;
        // Once the drag clearly follows one axis, claim it so the browser does
        // not read a horizontal drag as back-navigation.
        if (
          Math.abs(gesture.dx) > Math.abs(gesture.dy) * AXIS_RATIO ||
          gesture.dy > Math.abs(gesture.dx) * AXIS_RATIO
        ) {
          if (event.cancelable) event.preventDefault();
        }
      },
      { passive: false }
    );

    el.viewer.addEventListener(
      'touchend',
      function (event) {
        var gesture = state.gesture;
        if (!gesture.active) return;
        gesture.active = false;
        var dx = gesture.dx;
        var dy = gesture.dy;
        gesture.dx = 0;
        gesture.dy = 0;

        if (
          Math.abs(dx) >= SWIPE_MIN &&
          Math.abs(dx) > Math.abs(dy) * AXIS_RATIO
        ) {
          suppressClick();
          if (event.cancelable) event.preventDefault();
          show(dx < 0 ? 1 : -1);
        } else if (dy >= CLOSE_MIN && dy > Math.abs(dx) * AXIS_RATIO) {
          suppressClick();
          if (event.cancelable) event.preventDefault();
          close();
        }
      },
      { passive: false }
    );

    el.viewer.addEventListener(
      'touchcancel',
      function () {
        state.gesture.active = false;
        state.gesture.dx = 0;
        state.gesture.dy = 0;
      },
      { passive: true }
    );
  }

  // Recognised gestures still let some browsers synthesise a click; swallow
  // that click so it does not immediately close (or reopen) the viewer.
  function suppressClick() {
    state.gesture.suppressClick = true;
    setTimeout(function () {
      state.gesture.suppressClick = false;
    }, 400);
  }

  function close() {
    if (el.viewer.hidden) return;

    hideHint();
    el.viewer.hidden = true;
    state.loadToken += 1;
    state.album = [];
    state.albumIndex = 0;
    el.image.onload = null;
    el.image.onerror = null;
    el.image.removeAttribute('src');
    document.body.classList.remove('viewer-open');
    replaceHash('');
    status('');

    if (state.lastFocus && document.contains(state.lastFocus)) {
      state.lastFocus.focus({ preventScroll: true });
    }
  }

  function replaceHash(id) {
    var url = window.location.pathname + window.location.search;
    if (id) url += '#' + encodeURIComponent(id);
    window.history.replaceState(null, '', url);
  }

  function openFromHash() {
    var id = readHash();
    if (!id) return false;
    for (var i = 0; i < state.photos.length; i += 1) {
      if (state.photos[i].id === id) {
        open([state.photos[i]], 0);
        return true;
      }
    }
    return false;
  }

  /* -------------------------------------------------------------- wiring -- */

  function bindEvents() {
    el.viewer.addEventListener('click', function (event) {
      // Swallow the click a swipe or drag-down just synthesised.
      if (state.gesture.suppressClick) {
        state.gesture.suppressClick = false;
        return;
      }
      hideHint();
      // Only a click outside the photo's bounds closes the viewer. The image
      // keeps its aspect-ratio box from the width/height attributes even while
      // it loads, so this covers the spinner as well.
      var rect = el.image.getBoundingClientRect();
      if (
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom
      ) {
        return;
      }
      close();
    });

    bindTouchGestures();

    el.close.addEventListener('click', function (event) {
      event.stopPropagation();
      close();
    });

    el.prev.addEventListener('click', function (event) {
      event.stopPropagation();
      show(-1);
    });

    el.next.addEventListener('click', function (event) {
      event.stopPropagation();
      show(1);
    });

    document.addEventListener('keydown', function (event) {
      if (el.viewer.hidden) return;
      hideHint();
      if (event.key === 'Escape') {
        close();
      } else if (event.key === 'ArrowLeft') {
        event.preventDefault();
        show(-1);
      } else if (event.key === 'ArrowRight') {
        event.preventDefault();
        show(1);
      }
    });

    window.addEventListener('hashchange', function () {
      if (!openFromHash() && !el.viewer.hidden) close();
    });
  }

  function boot() {
    if (isTouch) document.body.classList.add('touch');
    cacheElements();
    bindEvents();
    initMap();

    fetch('photos.json', { cache: 'no-cache' })
      .then(function (response) {
        if (!response.ok) throw new Error(response.status + ' ' + response.statusText);
        return response.json();
      })
      .then(function (photos) {
        state.photos = Array.isArray(photos) ? photos : [];
        if (!state.photos.length) {
          status('No photos yet. Add files to photos/source and run make prep.');
          return;
        }
        drawPhotos();
        openFromHash();
      })
      .catch(function (error) {
        console.error(error);
        status(
          'photos.json could not be loaded. Serve this folder over HTTP ' +
            '(see the README) rather than opening the file directly.'
        );
      });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
